import string

def encode_shift(s: str) -> str:
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])

def decode_shift(s: str) -> str:
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return encode_shift(s, shift=-5)

# Helper function to decode with a given shift
def encode_shift(s: str, shift: int) -> str:
    """
    takes as input string and a shift value. Returns encoded string by shifting every character by the specified shift value.
    """
    return "".join([chr(((ord(ch) + shift - ord("a")) % 26) + ord("a")) for ch in s])
