def is_multiply_prime(a):
    """
    Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    while a % 2 == 0:
        a //= 2
        if a == 1:
            return True  # If a is reduced to 1, it means it was only 2 that multiplied the number.

    while a % 3 == 0:
        a //= 3
        if a == 1:
            return True  # If a is reduced to 1, it means it was only 3 that multiplied the number.

    if a > 1 and a < 100:
        return is_prime(a)  # If the remaining a is a prime number greater than 1.
    return False

# Example checks
print(is_multiply_prime(30))  # Expected: True
print(is_multiply_prime(100)) # Expected: False
print(is_multiply_prime(10))  # Expected: False
